import json
def A(n,t): return {"label":"USDA APHIS — pet travel from the United States to %s (relaying %s rules)"%(n,t),"url":"https://www.aphis.usda.gov/pet-travel/us-to-another-country-export/pet-travel-us-"+n.lower()}
S={
"ku":{"country":"Kuwait","src":A("Kuwait","Kuwaiti"),"head":"Kuwait requires a rabies antibody test and bans a long list of dog breeds.",
"lines":["The US agriculture department page on Kuwaiti entry says dogs, cats and ferrets need a rabies antibody (titer) test taken no less than 3 months and no more than 12 months before entering Kuwait, and a health certificate from an accredited vet endorsed by the US authority.","The page lists prohibited dog breeds, including Pit Bulls, Staffordshire and American Staffordshire Terriers, American Bully, all Mastiff types, Rottweilers, Doberman Pinschers, Caucasian Shepherds and Anatolian Shepherds, and any mix of them.","This is a US-side relay of Kuwaiti rules, so confirm with the Kuwaiti authority before travel."]},
"ma":{"country":"Morocco","src":A("Morocco","Moroccan"),"head":"Morocco's certificate is time-boxed: five business days to issue, three days to endorse, a final check within 24 hours.",
"lines":["The US agriculture department page on Moroccan entry says the pet must be identified by microchip or tattoo before its rabies vaccination, and that a four-page health certificate is used.","Pages 1 to 3 are issued within five business days of travel and endorsed within three calendar days; the pet is then re-examined by the issuing vet within 24 hours of departure, recorded on page 4, which needs no endorsement.","The certificate is valid for only three calendar days after endorsement. This is a US-side relay, so confirm with the Moroccan authority."]},
"my":{"country":"Malaysia","src":A("Malaysia","Malaysian"),"head":"Dogs and cats need a MAQIS import permit applied for online, plus an endorsed health certificate.",
"lines":["The US agriculture department page on Malaysian entry says a dog or cat must travel with a valid import permit from the Malaysian Quarantine and Inspection Services department (MAQIS) and an endorsed veterinary health certificate.","The permit application is made through the MAQIS online system, ePermit Dagangnet. Requirements for the animal itself are set out in the health certificate.","This is a US-side relay, so confirm with MAQIS before travel."]},
"co":{"country":"Colombia","src":A("Colombia","Colombian"),"head":"No import permit for personal pets, but a health certificate endorsed within 10 days of travel.",
"lines":["The US agriculture department page on Colombian entry says personal pet dogs and cats do not need an import permit.","They must carry a health certificate from an accredited vet endorsed within 10 days of travel, the rabies vaccination certificate, and at least one photocopy of the original certificate. Notarisation and a Colombian consular stamp are not needed.","The page says Colombia will reject pets that do not meet the certificate requirements. This is a US-side relay, so confirm with the Colombian agriculture institute."]},
"ua":{"country":"Ukraine","src":A("Ukraine","Ukrainian"),"head":"Microchip, rabies vaccine and an antibody titer of 0.5 IU/ml taken over three months before export.",
"lines":["The US agriculture department page on Ukrainian entry says personal dogs, cats and ferrets need an ISO microchip (or a pre-2011 tattoo) and an endorsed health certificate.","Pets over 12 weeks need a current rabies vaccine and a rabies titer of at least 0.5 IU/ml from an approved lab more than three months before export; the result stays valid while vaccination never lapses, and a lab copy goes with the certificate.","After a first vaccine, or a late booster, wait at least 21 days before travel. Pets of 12 to 16 weeks may travel if unvaccinated only under the no-wildlife-contact or vaccinated-mother conditions. This is a US-side relay."]}}
for k,v in S.items(): json.dump(v,open('dup_work/petspecs/%s.json'%k,'w',encoding='utf8'),ensure_ascii=False,separators=(',',':'))
